// unary negate
template <class T>
inline Array<T> negate(const Array<T>& a) {
    Array<T> out = a.copy();
    for (auto& v : *out.data) v = -v;
    return out;
}

// ------------------------------------------------------ comparison -> bool (P1)
// numpy comparisons broadcast and always return a bool array. The transpiler
// promotes both operands to a common dtype T before calling, so each compare is
// within-dtype here. numpy forbids chained array comparisons, so the transpiler
// only ever emits a SINGLE comparison op per expression.
enum class CmpOp { Eq, Ne, Lt, Le, Gt, Ge };

template <class T>
inline bool apply_cmp(CmpOp op, T a, T b) {
    switch (op) {
        case CmpOp::Eq: return a == b;
        case CmpOp::Ne: return a != b;
        case CmpOp::Lt: return a <  b;
        case CmpOp::Le: return a <= b;
        case CmpOp::Gt: return a >  b;
        case CmpOp::Ge: return a >= b;
    }
    return false;
}

template <class T>
inline Array<bool> compare(const Array<T>& a, const Array<T>& b, CmpOp op) {
    switch (op) {
        case CmpOp::Eq: return ew_binary<bool,T>(a, b, [](T x, T y){ return x == y; });
        case CmpOp::Ne: return ew_binary<bool,T>(a, b, [](T x, T y){ return x != y; });
        case CmpOp::Lt: return ew_binary<bool,T>(a, b, [](T x, T y){ return x <  y; });
        case CmpOp::Le: return ew_binary<bool,T>(a, b, [](T x, T y){ return x <= y; });
        case CmpOp::Gt: return ew_binary<bool,T>(a, b, [](T x, T y){ return x >  y; });
        case CmpOp::Ge: return ew_binary<bool,T>(a, b, [](T x, T y){ return x >= y; });
    }
    return ew_binary<bool,T>(a, b, [](T, T){ return false; });
}

template <class T> inline Array<bool> cmp_eq(const Array<T>& a, const Array<T>& b){ return compare(a,b,CmpOp::Eq); }
template <class T> inline Array<bool> cmp_ne(const Array<T>& a, const Array<T>& b){ return compare(a,b,CmpOp::Ne); }
template <class T> inline Array<bool> cmp_lt(const Array<T>& a, const Array<T>& b){ return compare(a,b,CmpOp::Lt); }
template <class T> inline Array<bool> cmp_le(const Array<T>& a, const Array<T>& b){ return compare(a,b,CmpOp::Le); }
template <class T> inline Array<bool> cmp_gt(const Array<T>& a, const Array<T>& b){ return compare(a,b,CmpOp::Gt); }
template <class T> inline Array<bool> cmp_ge(const Array<T>& a, const Array<T>& b){ return compare(a,b,CmpOp::Ge); }
// scalar-on-either-side overloads
template <class T> inline Array<bool> cmp_eq(const Array<T>& a, T s){ return compare(a,scalar<T>(s),CmpOp::Eq); }
template <class T> inline Array<bool> cmp_eq(T s, const Array<T>& a){ return compare(scalar<T>(s),a,CmpOp::Eq); }
template <class T> inline Array<bool> cmp_ne(const Array<T>& a, T s){ return compare(a,scalar<T>(s),CmpOp::Ne); }
template <class T> inline Array<bool> cmp_ne(T s, const Array<T>& a){ return compare(scalar<T>(s),a,CmpOp::Ne); }
template <class T> inline Array<bool> cmp_lt(const Array<T>& a, T s){ return compare(a,scalar<T>(s),CmpOp::Lt); }
template <class T> inline Array<bool> cmp_lt(T s, const Array<T>& a){ return compare(scalar<T>(s),a,CmpOp::Lt); }
template <class T> inline Array<bool> cmp_le(const Array<T>& a, T s){ return compare(a,scalar<T>(s),CmpOp::Le); }
template <class T> inline Array<bool> cmp_le(T s, const Array<T>& a){ return compare(scalar<T>(s),a,CmpOp::Le); }
